    while (getline(cin, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    size_t pos = 0;
    int n = stoi(lines[pos++]);
    int edgesLen = stoi(lines[pos++]);
    vector<vector<int>> edges(edgesLen, vector<int>(2));
    for (int i = 0; i < edgesLen; i++) {
        istringstream iss(lines[pos++]);
        iss >> edges[i][0] >> edges[i][1];
    }
    int source = stoi(lines[pos++]);
    int destination = stoi(lines[pos++]);
    bool result = solve(n, edges, source, destination);
    cout << (result ? "true" : "false") << "\n";
    return 0;
